import{c as r,Q as d,j as o,m as n}from"./chunks/framework.BPKcPtvA.js";const c=JSON.parse('{"title":"キーボードショートカット","description":"","frontmatter":{},"headers":[],"relativePath":"guide/keyboard-shortcuts.md","filePath":"guide/keyboard-shortcuts.md","lastUpdated":1786265066000}'),a={name:"guide/keyboard-shortcuts.md"};function s(e,t,g,l,h,i){return d(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="キーボードショートカット" tabindex="-1">キーボードショートカット <a class="header-anchor" href="#キーボードショートカット" aria-label="Permalink to &quot;キーボードショートカット&quot;">​</a></h1><p>設定画面の「キーボードショートカット」(折りたたみ) には、割り当てを変更できる 操作の現在値と、主な固定操作の一覧があり、 ライブラリ画面で <strong>Shift / Ctrl / Alt</strong> を押すと該当組み合わせのヒントが 画面左下にも出ます (= 修飾キーヒント)。</p><h2 id="全体の移動" tabindex="-1">全体の移動 <a class="header-anchor" href="#全体の移動" aria-label="Permalink to &quot;全体の移動&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キー</th><th>動作</th></tr></thead><tbody><tr><td><strong>Alt + ←</strong></td><td>戻る (履歴 1 つ前へ)</td></tr><tr><td><strong>Alt + →</strong></td><td>進む (戻った先から再度進む)</td></tr><tr><td><strong>マウスの戻るボタン</strong></td><td>戻る</td></tr><tr><td><strong>マウスの進むボタン</strong></td><td>進む</td></tr><tr><td><strong>Shift + ←</strong></td><td>前のトップタブへ (ライブラリ / ショップ / スキリスト / 設定 をループ)</td></tr><tr><td><strong>Shift + →</strong></td><td>次のトップタブへ (ループ)</td></tr><tr><td><strong>Ctrl + Shift + ←</strong></td><td>現在の画面の前のサブタブへ (ループ)</td></tr><tr><td><strong>Ctrl + Shift + →</strong></td><td>現在の画面の次のサブタブへ (ループ)</td></tr><tr><td><strong>Esc</strong></td><td>ダイアログ / 検索ボックス / プレビュー を閉じる</td></tr><tr><td><strong>Ctrl + F</strong></td><td>ライブラリ画面の検索ボックスへ移動</td></tr></tbody></table><p>履歴は <strong>タブ + 詳細画面</strong> を横断する 1 本の流れで管理しています。 ショップタブから商品詳細に飛んでも、戻ると元のショップに帰ります。</p><h2 id="ライブラリ画面-グリッド" tabindex="-1">ライブラリ画面 (グリッド) <a class="header-anchor" href="#ライブラリ画面-グリッド" aria-label="Permalink to &quot;ライブラリ画面 (グリッド)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キー</th><th>動作</th></tr></thead><tbody><tr><td><strong>←/→/↑/↓</strong></td><td>カード間の移動 (フォーカス)</td></tr><tr><td><strong>Home / End</strong></td><td>先頭 / 末尾のカードへ</td></tr><tr><td><strong>Enter</strong></td><td>フォーカス中のカードの詳細を開く</td></tr><tr><td><strong>Del</strong></td><td>確認なしでゴミ箱に移動 (通知の「元に戻す」で復元可)</td></tr><tr><td><strong>Ctrl + クリック</strong></td><td>一括選択モード ON + このカードを選択</td></tr><tr><td><strong>Shift + クリック</strong></td><td>BOOTH 商品ページを外部ブラウザで開く</td></tr><tr><td><strong>Ctrl + 右クリック</strong></td><td>この商品の未取得ファイルをダウンロード (非公開・対象外の旧版は除く)</td></tr><tr><td><strong>Ctrl + Shift + 右クリック</strong></td><td>このアイテムをゴミ箱へ (= すぐにゴミ箱へ)</td></tr></tbody></table><h2 id="一括選択モード" tabindex="-1">一括選択モード <a class="header-anchor" href="#一括選択モード" aria-label="Permalink to &quot;一括選択モード&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キー</th><th>動作</th></tr></thead><tbody><tr><td><strong>クリック</strong></td><td>選択の切替 (修飾キー無視)</td></tr><tr><td><strong>Shift + クリック</strong></td><td>連続範囲を選択</td></tr><tr><td><strong>Ctrl + A</strong></td><td>表示中の全カードを選択</td></tr><tr><td><strong>Ctrl + I</strong></td><td>表示中のカードの選択を反転</td></tr><tr><td><strong>Ctrl + D</strong></td><td>選択を解除 (モードは維持)</td></tr><tr><td><strong>Esc</strong></td><td>選択モード終了</td></tr><tr><td><strong>Ctrl + 右クリック</strong></td><td>選択モード終了 (マウスだけで終わるための手段)</td></tr><tr><td><strong>右クリック</strong></td><td>一括操作の右クリックメニュー (ダウンロード / カテゴリ / 削除 / エクスポート など)</td></tr></tbody></table><h2 id="商品詳細画面" tabindex="-1">商品詳細画面 <a class="header-anchor" href="#商品詳細画面" aria-label="Permalink to &quot;商品詳細画面&quot;">​</a></h2><p>左ペインのファイル一覧 (フォルダー / Unity Package タブ) と、右ペインのフォルダ内容を キーボードだけで操作できます。</p><table tabindex="0"><thead><tr><th>キー</th><th>動作</th></tr></thead><tbody><tr><td><strong>↑ / ↓</strong></td><td>ファイル一覧の行カーソルを移動 (まだ選択はしない)</td></tr><tr><td><strong>Enter</strong></td><td>カーソル中の行を選択 (右側に情報・プレビューを表示)</td></tr><tr><td><strong>← / →</strong></td><td>左ペインのタブを切替 (フォルダー ↔ Unity Package)</td></tr><tr><td><strong>Shift + ↑ / ↓</strong></td><td>複数選択できるリストで範囲選択</td></tr><tr><td><strong>Ctrl + A</strong></td><td>リストを全選択</td></tr><tr><td><strong>メニューキー</strong></td><td>選択行の操作メニュー (ダウンロード / 削除 / コピー / まとめて import など)</td></tr><tr><td><strong>Esc</strong></td><td>履歴の 1 つ前へ戻る (履歴がなければライブラリへ戻る)</td></tr><tr><td><strong>Alt + ←</strong> / <strong>マウスの戻るボタン</strong></td><td>戻る (履歴)</td></tr></tbody></table><p>これらはすべて設定の「ショートカットの変更 &gt; 詳細画面」で割り当て直せます。 グリッドと詳細は別画面なので、両方で ↑↓ などの同じキーを使っても衝突しません。</p><h2 id="スキリスト画面" tabindex="-1">スキリスト画面 <a class="header-anchor" href="#スキリスト画面" aria-label="Permalink to &quot;スキリスト画面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キー</th><th>動作</th></tr></thead><tbody><tr><td>ライブラリと同じ移動キー</td><td>グリッド内の移動 / Enter で商品ページを開く</td></tr><tr><td><strong>Home / End</strong></td><td>先頭 / 末尾のカードへ</td></tr><tr><td><strong>Del</strong></td><td>スキリストから削除 (= BOOTH 側も同時に削除)</td></tr><tr><td><strong>Ctrl + 左クリック</strong></td><td>一括選択</td></tr></tbody></table><h2 id="修飾キーヒント" tabindex="-1">修飾キーヒント <a class="header-anchor" href="#修飾キーヒント" aria-label="Permalink to &quot;修飾キーヒント&quot;">​</a></h2><p>ライブラリ画面で <strong>Shift</strong> や <strong>Ctrl</strong> を押すと、画面左下に 「このキーで何ができるか」のヒントが動的にポップアップします。</p><ul><li>例: <strong>Ctrl</strong> 押下中 → <code>Ctrl + クリック → 選択モード</code>, <code>Ctrl + 右クリック → 未取得ファイルをダウンロード</code></li><li>修飾キーを押している間だけ表示され、離すと消えます</li></ul><h2 id="カスタマイズ-割り当て直し" tabindex="-1">カスタマイズ (割り当て直し) <a class="header-anchor" href="#カスタマイズ-割り当て直し" aria-label="Permalink to &quot;カスタマイズ (割り当て直し)&quot;">​</a></h2><p>設定タブの「キーボードショートカット &gt; ショートカットの変更」から、 キーボード / マウス操作を自由に割り当て直しできます。</p><ol><li>変更したいコマンドの行をクリック</li><li>新しいキー操作 (またはマウス操作) を押す</li><li>確定 — 既に使われているキーには割り当てできません (警告が出ます)</li></ol><ul><li><strong>Esc</strong>: 割り当て直しをキャンセル</li><li><strong>↺ ボタン</strong>: そのコマンドをデフォルトのキーに戻す</li><li>方向キー (←/→/↑/↓) を含め各コマンドは割り当て直せます (「グリッド / スキリスト」「ライブラリのグリッド」「選択モード」 「詳細画面」「全体」のセクション別に一覧表示されます)</li></ul><p>設定タブの「ショートカット一覧」(折りたたみ) には現在の割り当てが一覧表示されます。</p>',23)])])}const u=r(a,[["render",s]]);export{c as __pageData,u as default};
